style.css:
@-moz-document domain("duartenunuofficialsite.odoo.com") {
/* Fundo preto profundo */
  body {
    background-color: #000 !important;
    color: #c0ffc0 !important;
    font-family: "Courier New", monospace !important;
    letter-spacing: 0.5px;
  }

  /* Texto com brilho neon estilo CRT */
  h1, h2, h3, p, span, a, .title, .oe_title {
    color: #c0ffc0 !important;
    text-shadow: 
      0 0 2px #0f0, 
      0 0 5px #0ff, 
      0 0 10px #fff;
  }

  /* Scanlines para efeito TV antiga */
  body::before {
    content: "";
    position: fixed;
    inset: 0;
    pointer-events: none;
    background-image: repeating-linear-gradient(
      rgba(0,0,0,0.15) 0 1px,
      transparent 1px 3px
    );
    z-index: 9999;
  }

  /* Tremor horizontal contínuo para simular interferência */
  @keyframes tvShake {
    0% { transform: translateX(0px); }
    25% { transform: translateX(1px); }
    50% { transform: translateX(-1px); }
    75% { transform: translateX(2px); }
    100% { transform: translateX(0px); }
  }

  body, .o_main_content, .o_website_content {
    animation: tvShake 0.2s infinite;
  }

  /* Efeito leve de desfoque e saturação exagerada nas imagens/blocos */
  img, video, iframe, picture, .card, .oe_structure, .o_form_sheet, .o_website_content {
    filter: blur(0.8px) contrast(1.6) saturate(1.8) !important;
  }

  /* Links clássicos dos anos 2000 */
  a, .o_link {
    color: #00f !important;
    text-decoration: underline !important;
  }

  a:hover {
    color: #0ff !important;
    text-shadow: 0 0 5px #0ff;
  }

  /* Cartões e blocos com bordas verdes neon e fundo semitransparente */
  .card, .o_card, .oe_structure, .o_form_sheet, .o_website_content {
    border: 2px solid #0f0 !important;
    border-radius: 4px !important;
    box-shadow: 0 0 10px #0f0 inset;
    background-color: rgba(0,0,0,0.6) !important;
  }

  /* Overlay de brilho radial simulando tubo CRT */
  body::after {
    content: "";
    position: fixed;
    inset: 0;
    pointer-events: none;
    background: radial-gradient(circle at 50% 50%, rgba(255,255,255,0.02), transparent 60%);
    mix-blend-mode: screen;
    z-index: 9998;
  }

  /* Pequeno efeito de estática intermitente */
  @keyframes staticNoise {
    0%, 100% { opacity: 0.03; }
    50% { opacity: 0.08; }
  }

  body::after {
    animation: staticNoise 0.15s infinite alternate;
  }
}
